			hint = [=[Lleve al mariscal los orbes oscuros de los lanzadores de hechizos Roca Negra.]=],
			text = [=[Los {link:blackrock-mountain}Roca Negra{/link} habían traído consigo lanzadores de sombras, y con ellos llegaron orbes de medianoche, corrompidos por demonios. Esos orbes habían abatido a muchos de los defensores de {link:redridge-mountains}Crestagrana{/link}. {link:the-marris-stead}Marris{/link} no quiso guardarlos. Los envió todos lejos para que fueran destruidos.]=],
		},
		{
			title = "Desaparecido en combate",
			hint = "Traiga a casa al soldado que se perdió en Petravista.",
			text = [=[El cabo {link:corporal-keeshan}Keeshan{/link} volvió de la {link:render-s-camp}Roca de Render{/link}, herido y solo. La mayor parte de su regimiento había muerto a su alrededor. {link:the-marris-stead}Marris{/link} lo consideró una victoria de todos modos, y recompensó a quienes habían traído al soldado a casa.]=],
