Translate("esES", "morganth", {
	title = "Morganth",
	subtitle = "Brujo de la Torre de Ilgalar",
	found = "Lo alto de la Torre de Ilgalar",
	hint = "Suba a la Torre de Ilgalar y enfréntese a su amo.",
	allegiance = "Él mismo · los gnolls Pellejo Negro",
	sections = {
		{
			title = "Resumen",
			text = [=[Morganth es un brujo humano que mora en la {link:tower-of-ilgalar}Torre de Ilgalar{/link}. Hace mucho estudió en la torre de los magos de {link:stormwind-city}Ventormenta{/link}, uno de tres que aprendieron allí juntos. Cayó en las artes oscuras, y cuando no quiso dar marcha atrás fue desterrado. Se llevó consigo un libro sellado de magia de las sombras. Ahora manda a los {link:shadowhide-gnolls}gnolls Pellejo Negro{/link}, les habla a través de colgantes encantados e invoca demonios a su lado.]=],
		},
		{
			title = "Importancia",
			text = [=[Morganth es el autor oculto de la ruina de {link:redridge-mountains}Crestagrana{/link}. Fue su magia la que alimentó el salvajismo de los {link:blackrock-mountain}Roca Negra{/link} en el {link:stonewatch-keep}Fuerte de Petravista{/link}. También es el rival del alto mago {link:theocritus}Theocritus{/link}, que lo vigila desde {link:elwynn-forest}Elwynn{/link} desde hace mucho tiempo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Se alió con {link:gath-ilzogg}Gath'Ilzogg{/link} y el {link:blackrock-clan}clan Roca Negra{/link}, y les ayudó a tomar el {link:stonewatch-keep}Fuerte de Petravista{/link}.
• Poco después se volvió contra los orcos, levantó su propia torre y sometió a su servicio a los {link:shadowhide-gnolls}gnolls Pellejo Negro{/link}.
• Guarda el Tratado de Ur sobre la magia de las sombras, aunque nunca rompió los sellos que los magos de {link:stormwind-city}Ventormenta{/link} le pusieron.
• Busca la {red:scythe-of-elune}Guadaña de Elune{/red}.]=],
		},
	},
	chapters = {
		{
			title = "La alianza rota",
			hint = "Ayude a Theocritus a mirar dentro del fuerte de los orcos.",
			text = [=[El Ojo de {link:tower-of-azora}Azora{/link} mostró a {link:theocritus}Theocritus{/link} un brujo en guerra con los orcos a los que antes había ayudado. Por qué se habían enemistado, ni siquiera el magistrado {link:magistrate-solomon}Solomon{/link} sabía decirlo. Para saber más, el alto mago escondió un glifo en lo alto de la atalaya junto al {link:stonewatch-keep}Fuerte de Petravista{/link}, y empezó a leer las mentes de los orcos de dentro.]=],
		},
		{
			title = "La Guadaña",
			hint = "Haga lo que Theocritus no está dispuesto a hacer él mismo.",
			text = [=[Al fin {link:theocritus}Theocritus{/link} supo lo que Morganth buscaba: la Guadaña de Elune. Temía que el brujo ya la hubiera encontrado, y que {link:stormwind-city}Ventormenta{/link} pronto sintiera su poder. El alto mago no quiso enfrentarse a Morganth en persona, así que otro subió a la {link:tower-of-ilgalar}Torre de Ilgalar{/link} en su lugar. El Colgante de las Sombras de Morganth volvió a {link:elwynn-forest}Elwynn{/link}, y Theocritus declaró que el reino se había salvado de un grave peligro.]=],
		},
	},
	mentions = {
		{ text = "La ley de {link:magistrate-solomon}Solomon{/link}" },
		{ text = "La recuperación de {link:theocritus}Theocritus{/link}" },
		{ text = "Un ojo vigilante" },
		{ text = "El Tratado de Ur sobre la magia de las sombras" },
	},
	bonds = {
		{ id = "theocritus", name = "Theocritus", note = "su rival" },
		{ id = "gath-ilzogg", name = "Gath'Ilzogg", note = "su antiguo aliado" },
		{ id = "lieutenant-fangore", name = "Teniente Fangore", note = "su teniente gnoll" },
		{ id = "shadowhide-gnolls", name = "Gnolls Pellejo Negro", note = "sus servidores" },
	},
})

