Translate("esES", "blackrock-clan", {
	title = "Clan Roca Negra",
	aliases = { "clan Roca Negra", "orcos Roca Negra" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los {link:blackrock-mountain}Roca Negra{/link} son uno de los clanes más antiguos y belicosos de los {link:orcs}orcos{/link}. Fueron la columna vertebral de la antigua {link:horde}Horda{/link} y le dieron dos de sus Jefes de Guerra. Mucho después de la derrota de la Horda, los Roca Negra han mantenido las viejas costumbres de la guerra, y nunca han hecho la paz con los humanos.]=],
		},
		{
			title = "Historia",
			text = [=[En la {link:first-war}Primera Guerra{/link}, el cabecilla Roca Negra Blackhand dirigió la {link:horde}Horda{/link} como su Jefe de Guerra, aunque otros movían los hilos detrás de él. Lo mató uno de los suyos, {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, un guerrero Roca Negra que después llevó a la Horda a la conquista de {link:stormwind-city}Ventormenta{/link}. En la {link:second-war}Segunda Guerra{/link}, la Horda de Doomhammer fue derrotada en la {link:blackrock-mountain}Montaña Roca Negra{/link} después de que él matara a {link:anduin-lothar}Anduin Lothar{/link}. La mayoría de los orcos fueron encerrados en campos. Los Roca Negra que escaparon se refugiaron en la montaña que lleva su nombre, y desde entonces han ocupado sus alturas.]=],
		},
		{
			title = "En Crestagrana",
			text = [=[Ahora los {link:blackrock-mountain}Roca Negra{/link} han bajado al sur desde {link:burning-steppes}Las Estepas Ardientes{/link}. A las órdenes del señor de la guerra {link:gath-ilzogg}Gath'Ilzogg{/link}, y con la magia oscura de {link:morganth}Morganth{/link}, tomaron el {link:stonewatch-keep}Fuerte de Petravista{/link} y derribaron el puente del {link:lake-everstill}Sempiterno{/link}. Sus batidores tienden emboscadas en los caminos, sus lanzadores de sombras llevan orbes corrompidos por demonios y sus campeones acampan junto al paso del norte. Otra banda de guerra ha entrado en el extremo sureste por el {link:render-s-valley}Valle de Render{/link}. Sin embargo, se han adentrado tanto en el reino que deben buscar comida y armas en las colinas, y {link:lakeshire}Villa del Lago{/link} espera rendirlos por hambre.]=],
		},
		{
			title = "La nueva Horda",
			text = [=[No todos los {link:blackrock-mountain}Roca Negra{/link} se quedaron con el clan. {link:eitrigg}Eitrigg{/link}, que antaño sirvió al jefe de guerra Roca Negra, llegó a odiar a los adoradores de demonios que extraviaron a su pueblo. Ahora sirve a {link:thrall}Thrall{/link} en {link:orgrimmar}Orgrimmar{/link}, lejos de la montaña de su antiguo clan.]=],
		},
	},
})

Translate("esES", "shadowhide-gnolls", {
	title = "Gnolls Pellejo Negro",
	aliases = { "gnolls Pellejo Negro", "Pellejo Negro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Pellejo Negro son un clan de {link:gnolls}gnolls{/link} que mora en el {link:galardell-valley}Valle de Galardell{/link}, en el nordeste de {link:redridge-mountains}Crestagrana{/link}. Sirven al brujo {link:morganth}Morganth{/link}. Su líder es el teniente {link:lieutenant-fangore}Fangore{/link}. Sus tejedores oscuros practican una magia sombría, sus asesinos golpean sin ser vistos y sus destripadores atacan a orcos y humanos por igual.]=],
		},
		{
			title = "Atados por colgantes",
			text = [=[Cada Pellejo Negro lleva un colgante a través del cual {link:morganth}Morganth{/link} les habla. El alto mago {link:theocritus}Theocritus{/link} lleva meses intentando penetrar en esos colgantes. Ha logrado enviar un mensaje a través de algunos de ellos, y espera algún día enviar a través de ellos un ataque que paralice a todos los gnolls que los lleven.]=],
		},
		{
			title = "Ante la ley",
			text = [=[El tribunal de {link:lakeshire}Villa del Lago{/link} declaró a los Pellejo Negro culpables de ayudar a un criminal del reino, un delito castigado con la muerte. El alguacil {link:bailiff-conacher}Conacher{/link} paga por sus colgantes como prueba, y el magistrado ha puesto precio a la cabeza del propio {link:lieutenant-fangore}Fangore{/link}.]=],
		},
		{
			title = "Enemigos de todos",
			text = [=[Los Pellejo Negro no son amigos de los {link:blackrock-mountain}Roca Negra{/link}. Cuando {link:morganth}Morganth{/link} se volvió contra sus aliados orcos, sus gnolls se volvieron con él, y a sus manos han muerto tanto orcos como hombres.]=],
		},
	},
})

Translate("esES", "redridge-gnolls", {
	title = "Gnolls Crestagrana",
	aliases = { "gnolls Crestagrana", "manada Crestagrana" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los gnolls Crestagrana son la vieja manada de gnolls de las {link:redridge-mountains}Montañas Crestagrana{/link}, distinta de los {link:shadowhide-gnolls}Pellejo Negro{/link} que sirven a {link:morganth}Morganth{/link}. No sirven a ningún brujo ni a ningún {link:orcs}orco{/link}. Sus brutos y místicos recorren las colinas al norte de {link:lakeshire}Villa del Lago{/link}, y sus cazadores furtivos y chuchos acampan a lo largo del camino del sur. Su líder es {link:yowler}Yowler{/link}, que tiene su cubil en los {link:redridge-canyons}Cañones de Crestagrana{/link}, y cuyo aullido llega hasta Villa del Lago.]=],
		},
		{
			title = "Sus costumbres",
			text = [=[Los gnolls Crestagrana toman lo que la guerra deja sin vigilancia. Se apoderaron de la caravana que llevaba hierro para el puente del {link:lake-everstill}Sempiterno{/link}. Roban caballos del establo de {link:lakeshire}Villa del Lago{/link}. Se han instalado en las {link:rethban-caverns}Cavernas de Rethban{/link}, donde sus peones extraen el mineral que antes minaba la población. Están poco organizados, pero respetan la fuerza por encima de todo. El ayudante {link:deputy-feldon}Feldon{/link} espera que la muerte de sus apaleadores más feroces enseñe a los demás a quedarse en las colinas. En Rethban, un {link:gnolls}gnoll{/link} llamado Ardo Dirtpaw dirige la manada que ocupa las cavernas.]=],
		},
	},
})
